const ts = require('/opt/typescript/lib/typescript.js');
const fs = require('fs');
const path = require('path');
const context = JSON.parse(fs.readFileSync('/work/context.json', 'utf8'));
const root = context.workspace;
const files = context.files.filter(f => f.endsWith('.ts'));
const config = ts.readConfigFile(path.join(root,'tsconfig.json'), ts.sys.readFile);
const options = ts.convertCompilerOptionsFromJson(config.config.compilerOptions,root).options;
const program = ts.createProgram(files.map(f=>path.join(root,f)), options);
const checker = program.getTypeChecker();
const sf = program.getSourceFile(path.join(root,'src/type/definition.ts'));
const target = checker.getExportsOfModule(checker.getSymbolAtLocation(sf)).find(s=>s.name==='getNamedType');
function resolve(s) { return s && (s.flags & ts.SymbolFlags.Alias ? checker.getAliasedSymbol(s) : s); }
const references=[];
const excluded=[];
for (const file of files) {
 const source=program.getSourceFile(path.join(root,file));
 function visit(node) {
  if (ts.isIdentifier(node)) {
   const symbol=resolve(checker.getSymbolAtLocation(node));
   if(symbol===target) {
    const start=source.getLineAndCharacterOfPosition(node.getStart(source));
    const end=source.getLineAndCharacterOfPosition(node.getEnd());
    const row={target:'getNamedType',file,line:start.line+1,column:start.character,end_line:end.line+1,end_column:end.character};
    if(ts.isFunctionDeclaration(node.parent) && node.parent.name===node) excluded.push(row);
    else references.push(row);
   }
  }
  ts.forEachChild(node,visit);
 }
 visit(source);
}
references.sort((a,b)=>a.file.localeCompare(b.file)||a.line-b.line||a.column-b.column);
